=== CityRegion ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Fixed city-to-region lookup used to derive an owner's {@code locality}.
 *
 * <p>The table is intentionally closed: only Sydney, Melbourne and Brisbane map to a
 * canonical region. Any other (or missing) city derives the locality {@code "UNKNOWN"}.
 */
public final class CityRegion {

    /** City (case-insensitive) -> canonical region. */
    private static final Map<String, String> CITY_REGION = Map.of(
        "sydney", "NSW",
        "melbourne", "VIC",
        "brisbane", "QLD");

    /** Region -> inclusive {low, high} 4-digit postcode range. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
        "NSW", new int[] {2000, 2099},
        "VIC", new int[] {3000, 3099},
        "QLD", new int[] {4000, 4099});

    /** Locality returned when the city is not in {@link #CITY_REGION}. */
    public static final String UNKNOWN = "UNKNOWN";

    private CityRegion() {
    }

    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not in the table. */
    public static String localityOf(String city) {
        if (city == null) {
            return UNKNOWN;
        }
        return CITY_REGION.getOrDefault(city.trim().toLowerCase(Locale.ROOT), UNKNOWN);
    }

    /**
     * The canonical region, preferring the {@code postcode}: the region whose range contains the
     * postcode is returned first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). Only when the
     * postcode is absent, non-numeric or in no known range does this fall back to the city-to-region
     * table. Returns {@code "UNKNOWN"} when neither yields a region.
     */
    public static String localityOf(String city, String postcode) {
        String byPostcode = regionForPostcode(postcode);
        return byPostcode != null ? byPostcode : localityOf(city);
    }

    /** The region whose inclusive range contains {@code postcode}, or {@code null} when none does. */
    private static String regionForPostcode(String postcode) {
        if (postcode == null) {
            return null;
        }
        int value;
        try {
            value = Integer.parseInt(postcode.trim());
        }
        catch (NumberFormatException ex) {
            return null;
        }
        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }

    /**
     * The inclusive {@code {low, high}} postcode range for {@code city}'s region, or {@code null}
     * when the city has no known region (in which case any 4-digit postcode is accepted).
     */
    public static int[] postcodeRangeOf(String city) {
        return REGION_POSTCODES.get(localityOf(city));
    }
}
=== OwnerIdentity ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
 * through.
 *
 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Two owners
 * are duplicates only when their <em>whole</em> keys are equal (see {@link CheckIdentityUnique}).
 * Because the telephone is part of the key, two members of the same household (same
 * {@code householdId}) with different telephones have different keys and are both allowed.
 *
 * <p>The three components are normalized so the key is stable: the telephone to E.164 form (see
 * {@link TelephoneE164}), the email lower-cased and trimmed, and a null household rendered as empty.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /** The identity key of a persisted owner, from its stored telephone, email and householdId. */
    public static String of(Owner owner) {
        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /** Assemble the identity key from the three components, normalizing telephone and email. */
    public static String key(String telephone, String email, String householdId) {
        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|"
                + (householdId == null ? "" : householdId);
    }

    /**
     * The stable, shared household identifier for an owner's last name and address, normalizing both
     * the canonical way first (last name lower-cased with whitespace collapsed; address via
     * {@link AddressNormalizer}). Owners living at the same address under the same last name get the
     * same value regardless of creation order.
     */
    public static String householdIdFor(String lastName, String address) {
        return householdId(normalizeLastName(lastName), AddressNormalizer.normalize(address));
    }

    /** First 16 upper-case hex chars of SHA-256(lastName|address), over already-normalized inputs. */
    private static String householdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(32);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 16).toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** Telephone in E.164 form for comparison; null/invalid becomes empty. */
    private static String normalizeTelephone(String telephone) {
        String e164 = TelephoneE164.normalize(telephone);
        return e164 == null ? "" : e164;
    }

    /** Email lower-cased and trimmed so comparison ignores case; null/blank becomes empty. */
    private static String normalizeEmail(String email) {
        if (email == null) {
            return "";
        }
        return email.trim().toLowerCase(Locale.ROOT);
    }

    /** Last name lower-cased with runs of whitespace collapsed, so comparison ignores case/spacing. */
    private static String normalizeLastName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
=== TelephoneE164 ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Normalizes a telephone number to E.164 form.
 *
 * <p>Rules: strip spaces, dashes and brackets; keep a leading '+' and country code when
 * present, otherwise assume country code '+61' and drop a single leading '0' from the
 * national digits. The result is {@code '+'} followed by 8 to 15 digits; anything that
 * cannot form a valid E.164 number yields {@code null}.
 *
 * <p>The national number's length is validated against its country code: a {@code '+61'}
 * (Australia) number requires exactly 9 national digits and a {@code '+1'} (NANP) number
 * requires exactly 10; a number whose national part is the wrong length for its country
 * yields {@code null}.
 *
 * <p>Example: {@code "0412 345 678"} becomes {@code "+61412345678"}.
 */
final class TelephoneE164 {

    /** Characters removed before interpreting the number: spaces, dashes and brackets. */
    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()]");

    /**
     * Country code (without '+') to its required national-number length. Ordered
     * longest-prefix-first so a code such as {@code "61"} is matched before {@code "1"}.
     */
    private static final Map<String, Integer> NATIONAL_LENGTHS = new LinkedHashMap<>();

    static {
        NATIONAL_LENGTHS.put("61", 9);
        NATIONAL_LENGTHS.put("1", 10);
    }

    private TelephoneE164() {
    }

    /**
     * Convert to E.164, or return {@code null} when the input cannot form a valid number.
     */
    static String normalize(String raw) {
        if (raw == null) {
            return null;
        }
        String trimmed = raw.trim();
        boolean hasCountryCode = trimmed.startsWith("+");
        String cleaned = SEPARATORS.matcher(trimmed).replaceAll("");
        String digits;
        if (hasCountryCode) {
            // Keep the given country code; the '+' is re-added below.
            digits = cleaned.substring(1);
        }
        else {
            // No country code: assume '+61' and drop a single leading national '0'.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.chars().allMatch(Character::isDigit) || digits.isEmpty()) {
            return null;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            return null;
        }
        // Validate the national-number length against the country code (e.g. '+61' => 9
        // national digits, '+1' => 10). Codes are checked longest-prefix-first.
        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTHS.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code)) {
                int nationalLength = digits.length() - code.length();
                if (nationalLength != entry.getValue()) {
                    return null;
                }
                break;
            }
        }
        return "+" + digits;
    }
}
=== AddressNormalizer ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Normalizes a street address to a canonical stored form.
 *
 * <p>Rules: trim the ends, collapse every run of whitespace to a single space, upper-case the
 * whole string, then expand common abbreviations as whole words: {@code ST -> STREET},
 * {@code RD -> ROAD}, {@code AVE -> AVENUE}. Expansion is token-based, so an abbreviation embedded
 * in a longer word (e.g. {@code STANMORE}) is left untouched. A {@code null} or all-whitespace
 * input yields the empty string, which the required-field check treats as a blank address.
 *
 * <p>Example: {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
 */
final class AddressNormalizer {

    /** Any run of whitespace, collapsed to a single space. */
    private static final Pattern WHITESPACE = Pattern.compile("\\s+");

    private AddressNormalizer() {
    }

    /** Convert to the canonical stored form; {@code null}/blank input yields {@code ""}. */
    static String normalize(String raw) {
        if (raw == null) {
            return "";
        }
        String collapsed = WHITESPACE.matcher(raw.trim()).replaceAll(" ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    /** Expand a single whole-word abbreviation, or return the token unchanged. */
    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
=== CheckIdentityUnique ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects creating an owner whose {@code identityKey} exactly equals an existing owner's, so the
 * create endpoint responds 409 instead of storing a duplicate. This single check replaces the former
 * separate telephone, email and household checks: all duplicate detection is now expressed through
 * the one key {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
 * {@link OwnerIdentity}).
 *
 * <p>Only a whole-key match is a duplicate. Because the telephone is part of the key, two members of
 * the same household (same {@code householdId}) with different telephones have different keys and are
 * both allowed. The new owner's household component matches what {@link AssignHousehold} will assign:
 * a shared id when the request opts in with {@code sharesHousehold: true}, otherwise empty.
 *
 * <p>Runs after {@link ValidateOwner} (which normalizes and publishes the body) and before
 * {@link BuildOwner}, comparing against every existing owner's identity key.
 */
public class CheckIdentityUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String householdId = Boolean.TRUE.equals(request.getSharesHousehold())
                ? OwnerIdentity.householdIdFor(request.getLastName(), request.getAddress())
                : "";
        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(OwnerIdentity.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
=== AssignHousehold ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Assigns a shared {@code householdId} when the request opts in with {@code sharesHousehold: true}.
 *
 * <p>The identifier is derived deterministically from the normalized last name and address (see
 * {@link OwnerIdentity#householdIdFor}), so it is stable: every owner living at the same address
 * under the same last name gets the same value regardless of creation order. The new owner and every
 * existing owner in that household are stamped with it, so both sides of an intentionally shared
 * household report the identifier. When {@code sharesHousehold} is not true no identifier is assigned,
 * and the owner's identity key (see {@link OwnerIdentity}) uses an empty household component.
 *
 * <p>Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String householdId = OwnerIdentity.householdIdFor(owner.getLastName(), owner.getAddress());
        owner.setHouseholdId(householdId);
        // Stamp existing members of the same household so both sides share the identifier.
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(OwnerIdentity.householdIdFor(existing.getLastName(), existing.getAddress()))
                    && !householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }
}
=== AssignNamesakeCount ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's {@code namesakeCount}: the number of existing owners that already share this
 * owner's first name and last name, compared case-insensitively, at the moment of creation.
 *
 * <p>The new owner is not yet saved when this runs, so {@link OwnerRepository#findAll()} returns only
 * the pre-existing owners — the count excludes the owner being created. It is zero when the name is
 * unique. Runs after {@link BuildOwner} (which publishes the new owner) and before {@link SaveOwner}.
 */
public class AssignNamesakeCount {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = normalize(owner.getFirstName());
        String lastName = normalize(owner.getLastName());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equals(normalize(existing.getFirstName()))
                    && lastName.equals(normalize(existing.getLastName()))) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    /** Lower-cases and trims so the comparison ignores case and surrounding whitespace. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().toLowerCase(Locale.ROOT);
    }
}

